import "../css/mainPage.css";

import React, { useState, useEffect } from "react";
import { useNavigate } from "react-router-dom";

import logo from "../image/tybwhitelogo.png";
import logoblack from "../image/tyblogoblack.jpeg";
import esign1 from "../image/georgeEsign.jpeg";

import DashboardIcon from "@mui/icons-material/Dashboard";
import PrintIcon from "@mui/icons-material/Print";

const units = ["kg", "gms", "pcs"];

const productForCustomers = [
    "Filter Coffee",
    "Instant Coffee",
    "Coffee Bean",
    "Pepper",
    "Honey",
    "Small combo",
    "Medium combo",
    "Big combo"
];

const API_BASE_URL = "http://localhost:5000";

const msme = process.env.REACT_APP_MSME;

function MainPage() {
    const navigate = useNavigate();

    // ============================================================
    // RESORT BILLING
    // ============================================================

    const [resortCustomers, setResortCustomers] = useState([]);
    const [resortProducts, setResortProducts] = useState([]);

    const [customer, setCustomer] = useState("");
    const [product, setProduct] = useState("");
    const [quantity, setQuantity] = useState(1);

    const [cart, setCart] = useState([]);

    const [billNo, setBillNo] = useState(1);
    const [balance, setBalance] = useState();

    const [isManual, setIsManual] = useState(false);
    const [selectedDate, setSelectedDate] = useState("");

    const [savingOrder, setSavingOrder] = useState(false);
    const [orderSaved, setOrderSaved] = useState(false);

    // ============================================================
    // NORMAL CUSTOMER BILLING
    // ============================================================

    const [cust, setCust] = useState("");
    const [addr, setAddr] = useState("");
    const [custProduct, setCustProduct] = useState("");
    const [custQuanity, setCustQuantity] = useState("");
    const [custunit, setCustUnit] = useState("");
    const [customerPrice, setCustomerPrice] = useState();
    const [customerCart, setCustomerCart] = useState([]);

    // ============================================================
    // FETCH RESORT CUSTOMERS
    // ============================================================

    useEffect(() => {
        fetchResortCustomers();
    }, []);

    const fetchResortCustomers = async () => {
        try {
            const response = await fetch(
                `${API_BASE_URL}/api/resort-customers`
            );

            if (!response.ok) {
                throw new Error("Failed to fetch resort customers");
            }

            const data = await response.json();

            setResortCustomers(data);
        } catch (error) {
            console.error(
                "Error fetching resort customers:",
                error
            );
        }
    };

    // ============================================================
    // FETCH PRODUCTS FOR SELECTED RESORT
    // ============================================================

    const fetchResortProducts = async (customerId) => {
        try {
            const response = await fetch(
                `${API_BASE_URL}/api/resort-customers/${customerId}/products`
            );

            if (!response.ok) {
                throw new Error(
                    "Failed to fetch products for resort"
                );
            }

            const data = await response.json();

            setResortProducts(data);
        } catch (error) {
            console.error(
                "Error fetching resort products:",
                error
            );

            setResortProducts([]);
        }
    };

    // ============================================================
    // CUSTOMER CHANGE
    // ============================================================

    const handleResortCustomerChange = async (e) => {
        const customerId = e.target.value;

        setCustomer(customerId);
        setProduct("");
        setQuantity(1);
        setOrderSaved(false);

        if (!customerId) {
            setResortProducts([]);
            return;
        }

        await fetchResortProducts(customerId);
    };

    // ============================================================
    // SELECTED RESORT CUSTOMER
    // ============================================================

    const selectedResortCustomer = resortCustomers.find(
        (c) =>
            String(c.resort_customer_id) === String(customer)
    );

    // ============================================================
    // SELECTED PRODUCT / COMBO
    // ============================================================

    const selectedProduct = resortProducts.find((p) => {
        const selectedValue = product;

        if (p.combo_id !== null && p.combo_id !== undefined) {
            return `combo-${p.combo_id}` === selectedValue;
        }

        return (
            `variant-${p.product_variant_id}` ===
            selectedValue
        );
    });

    // ============================================================
    // PRICE
    // ============================================================

    const price = selectedProduct
        ? Number(selectedProduct.price)
        : 0;

    const totalPrice =
        price * Number(quantity || 0);

    // ============================================================
    // ADD RESORT ITEM
    // ============================================================

    const handleAdd = () => {
        if (!customer) {
            alert("Please select a resort customer.");
            return;
        }

        if (!product) {
            alert("Please select a product.");
            return;
        }

        if (!quantity || quantity <= 0) {
            alert("Please enter a valid quantity.");
            return;
        }

        if (!selectedProduct) {
            alert("Product details not found.");
            return;
        }

        const newItem = {
            id: Date.now(),

            resortCustomerId:
                Number(customer),

            productVariantId:
                selectedProduct.product_variant_id ??
                null,

            comboId:
                selectedProduct.combo_id ??
                null,

            product:
                selectedProduct.product_name,

            packSize:
                selectedProduct.pack_size_grams ??
                null,

            quantity:
                Number(quantity),

            price:
                Number(selectedProduct.price),

            total:
                Number(selectedProduct.price) *
                Number(quantity)
        };

        setCart((prevCart) => [
            ...prevCart,
            newItem
        ]);

        // Reset product and quantity.
        // Customer remains selected.
        setProduct("");
        setQuantity(1);
        setOrderSaved(false);
    };

    // ============================================================
    // DELETE RESORT ITEM
    // ============================================================

    const handleDelete = (id) => {
        setCart((prevCart) =>
            prevCart.filter(
                (item) => item.id !== id
            )
        );

        setOrderSaved(false);
    };

    // ============================================================
    // NEW BILL
    // ============================================================

    const handleNewBill = () => {
        if (savingOrder) {
            return;
        }

        setCustomer("");
        setProduct("");
        setQuantity(1);

        setResortProducts([]);
        setCart([]);

        setBalance(undefined);

        setOrderSaved(false);
        setSavingOrder(false);

        setBillNo((prev) => prev + 1);
    };

    // ============================================================
    // SAVE RESORT ORDER
    // ============================================================

  const saveResortOrder = async () => {
    if (!customer) {
        return true;
    }

    if (cart.length === 0) {
        return true;
    }

    if (orderSaved) {
        return true;
    }

    try {
        setSavingOrder(true);

        const items = cart.map((item) => ({
            productVariantId: item.productVariantId,
            comboId: item.comboId,
            quantity: item.quantity,
            price: item.price
        }));

        const response = await fetch(
            `${API_BASE_URL}/api/resort-customers/${customer}/orders`,
            {
                method: "POST",

                headers: {
                    "Content-Type": "application/json"
                },

                body: JSON.stringify({
                    orderDate: selectedDate,
                    totalAmount: Number(grandTotal),
                    items
                })
            }
        );

        const data = await response.json();

        if (!response.ok) {
            throw new Error(
                data.message || "Failed to save order"
            );
        }

        console.log(
            "Resort order saved:",
            data
        );

        setOrderSaved(true);

        return true;

    } catch (error) {

        console.error(
            "Error saving resort order:",
            error
        );

        alert(
            "Failed to save the order. Please try again."
        );

        return false;

    } finally {

        setSavingOrder(false);

    }
};

    // ============================================================
    // NORMAL CUSTOMER BILLING
    // ============================================================

    let custTotalPrice;

    if (custunit === "gms") {
        custTotalPrice =
            (Number(custQuanity) / 1000) *
            Number(customerPrice || 0);
    } else {
        custTotalPrice =
            Number(customerPrice || 0) *
            Number(custQuanity || 0);
    }

    const handleAddCustomer = () => {
        if (
            !cust ||
            !custProduct ||
            !custQuanity ||
            custQuanity <= 0
        ) {
            return;
        }

        const cartItem = {
            id: Date.now(),

            cust,
            addr,
            custProduct,
            custQuanity,
            custunit,
            customerPrice,
            custtotal: custTotalPrice
        };

        setCustomerCart((prevCart) => [
            ...prevCart,
            cartItem
        ]);

        setCustProduct("");
        setCustQuantity(1);
    };

    const handleDeleteForCustomers = (id) => {
        setCustomerCart((prevCart) =>
            prevCart.filter(
                (item) => item.id !== id
            )
        );
    };

    // ============================================================
    // GRAND TOTAL
    // ============================================================

    let grandTotal = 0;

    if (cart.length > 0) {
        grandTotal = cart.reduce(
            (sum, item) =>
                sum + Number(item.total),
            0
        );

        if (balance) {
            grandTotal += Number(balance);
        }
    } else {
        grandTotal = customerCart.reduce(
            (sum, item) =>
                sum + Number(item.custtotal),
            0
        );
    }

    // ============================================================
    // NUMBER TO WORDS
    // ============================================================

    function numberToWords(num) {
        const ones = [
            "",
            "One",
            "Two",
            "Three",
            "Four",
            "Five",
            "Six",
            "Seven",
            "Eight",
            "Nine",
            "Ten",
            "Eleven",
            "Twelve",
            "Thirteen",
            "Fourteen",
            "Fifteen",
            "Sixteen",
            "Seventeen",
            "Eighteen",
            "Nineteen"
        ];

        const tens = [
            "",
            "",
            "Twenty",
            "Thirty",
            "Forty",
            "Fifty",
            "Sixty",
            "Seventy",
            "Eighty",
            "Ninety"
        ];

        function convert(n) {
            if (n === 0) {
                return "";
            }

            if (n < 20) {
                return ones[n];
            }

            if (n < 100) {
                return (
                    tens[Math.floor(n / 10)] +
                    " " +
                    ones[n % 10]
                );
            }

            if (n < 1000) {
                return (
                    ones[Math.floor(n / 100)] +
                    " Hundred " +
                    convert(n % 100)
                );
            }

            if (n < 100000) {
                return (
                    convert(
                        Math.floor(n / 1000)
                    ) +
                    " Thousand " +
                    convert(n % 1000)
                );
            }

            if (n < 10000000) {
                return (
                    convert(
                        Math.floor(n / 100000)
                    ) +
                    " Lakh " +
                    convert(n % 100000)
                );
            }

            return (
                convert(
                    Math.floor(n / 10000000)
                ) +
                " Crore " +
                convert(n % 10000000)
            );
        }

        if (!num || num === 0) {
            return "Zero Only";
        }

        return (
            convert(Math.floor(num)) +
            " Only"
        );
    }

    // ============================================================
    // DATE
    // ============================================================

    const currentDate = new Date();

    const date =
        currentDate
            .toISOString()
            .split("T")[0];

    useEffect(() => {
        if (!isManual) {
            setSelectedDate(date);
        }
    }, [isManual, date]);

    const formatDate = (dateStr) => {
        if (!dateStr) {
            return "";
        }

        const [
            year,
            month,
            day
        ] = dateStr.split("-");

        return `${day}/${month}/${year}`;
    };

    // ============================================================
    // PRINT
    // ============================================================

    const handlePrint = async () => {
        // Only save resort order if resort cart is being used.
        if (
            customer &&
            cart.length > 0
        ) {
            const saved =
                await saveResortOrder();

            if (!saved) {
                return;
            }
        }

        window.print();
    };

    // ============================================================
    // BALANCE SERIAL NUMBER
    // ============================================================

    const balanceSNo =
        cart.length +
        customerCart.length +
        1;

    // ============================================================
    // UI
    // ============================================================

    return (
        <div className="maindiv">

            {/* =====================================================
                HEADER
            ===================================================== */}

            <div className="header">

                <div>

                    <img
                        src={logo}
                        alt="logo"
                    />

                    <br />

                    <span
                        style={{
                            color: "white",
                            paddingLeft: "20px"
                        }}
                    >
                        The Yercaud Bean
                    </span>

                </div>

                <div>

                    <button
                        onClick={() =>
                            navigate("/dashboard")
                        }
                    >
                        <DashboardIcon />
                    </button>

                    <button
                        onClick={() =>
                            navigate("/courier")
                        }
                    >
                        <PrintIcon />
                    </button>

                </div>

            </div>

            <div className="mainbody">

                {/* =================================================
                    RESORT BILLING
                ================================================= */}

                <h2>
                    Credit Bill
                </h2>

                {/* DATE + BILL NUMBER */}

                <div className="selectDateandBillNo">

                    <div>

                        <input
                            type="date"
                            style={{
                                marginRight: "10px",
                                paddingTop: "3px",
                                paddingBottom: "3px"
                            }}
                            value={selectedDate}
                            onChange={(e) =>
                                setSelectedDate(
                                    e.target.value
                                )
                            }
                            disabled={!isManual}
                        />

                        <button
                            onClick={() =>
                                setIsManual(
                                    !isManual
                                )
                            }
                        >
                            {isManual
                                ? "Today"
                                : "Custom"}
                        </button>

                    </div>

                    <div>

                        <input
                            type="number"
                            placeholder="Bill No"
                            value={billNo}
                            onChange={(e) =>
                                setBillNo(
                                    Number(
                                        e.target.value
                                    )
                                )
                            }
                            style={{
                                marginRight: "10px",
                                marginBottom: "10px",
                                paddingTop: "3px",
                                paddingBottom: "3px",
                                border: "2px solid black",
                                borderRadius: "5px",
                                paddingLeft: "5px"
                            }}
                        />

                    </div>

                </div>

                {/* =================================================
                    RESORT CUSTOMER / PRODUCT / QUANTITY
                ================================================= */}

                <div className="inputDetails">

                    {/* RESORT CUSTOMER */}

                    <select
                        style={{
                            width: "300px",
                            border: "2px solid black",
                            borderRadius: "5px",
                            paddingTop: "10px",
                            paddingBottom: "10px",
                            paddingLeft: "5px"
                        }}
                        value={customer}
                        onChange={
                            handleResortCustomerChange
                        }

                        /*
                         * IMPORTANT:
                         *
                         * Once an item is added, the customer
                         * cannot be changed.
                         *
                         * This guarantees:
                         *
                         * One bill -> One customer
                         */
                        disabled={
                            cart.length > 0
                        }
                    >

                        <option value="">
                            Select customer
                        </option>

                        {resortCustomers.map(
                            (c) => (
                                <option
                                    key={
                                        c.resort_customer_id
                                    }
                                    value={
                                        c.resort_customer_id
                                    }
                                >
                                    {
                                        c.customer_name
                                    }
                                </option>
                            )
                        )}

                    </select>

                    {/* PRODUCT / COMBO */}

                    <select
                        style={{
                            width: "300px",
                            border: "2px solid black",
                            borderRadius: "5px",
                            paddingTop: "10px",
                            paddingBottom: "10px",
                            paddingLeft: "5px"
                        }}
                        value={product}
                        onChange={(e) =>
                            setProduct(
                                e.target.value
                            )
                        }
                        disabled={!customer}
                    >

                        <option value="">
                            Select product
                        </option>

                        {resortProducts.map(
                            (p) => {

                                const isCombo =
                                    p.combo_id !==
                                        null &&
                                    p.combo_id !==
                                        undefined;

                                const value =
                                    isCombo
                                        ? `combo-${p.combo_id}`
                                        : `variant-${p.product_variant_id}`;

                                let displayName =
                                    p.product_name;

                                if (isCombo) {
                                    displayName =
                                        p.combo_name ||
                                        p.product_name ||
                                        `Combo ${p.combo_id}`;
                                }

                                if (
                                    p.pack_size_grams
                                ) {
                                    displayName +=
                                        ` (${p.pack_size_grams}g)`;
                                }

                                return (
                                    <option
                                        key={value}
                                        value={value}
                                    >
                                        {displayName}
                                    </option>
                                );
                            }
                        )}

                    </select>

                    {/* QUANTITY */}

                    <input
                        style={{
                            width: "290px",
                            border: "2px solid black",
                            borderRadius: "5px",
                            paddingTop: "10px",
                            paddingBottom: "10px",
                            paddingLeft: "5px"
                        }}
                        type="number"
                        placeholder="Enter quantity"
                        value={quantity}
                        min="1"
                        onChange={(e) =>
                            setQuantity(
                                Number(
                                    e.target.value
                                )
                            )
                        }
                    />

                    {/* PRICE */}

                    <input
                        style={{
                            width: "290px",
                            border: "2px solid black",
                            borderRadius: "5px",
                            paddingTop: "10px",
                            paddingBottom: "10px",
                            paddingLeft: "5px"
                        }}
                        type="text"
                        value={
                            selectedProduct
                                ? `₹${price}`
                                : ""
                        }
                        readOnly
                        placeholder="Price"
                    />

                    {/* TOTAL */}

                    <input
                        style={{
                            width: "290px",
                            border: "2px solid black",
                            borderRadius: "5px",
                            paddingTop: "10px",
                            paddingBottom: "10px",
                            paddingLeft: "5px"
                        }}
                        type="text"
                        value={
                            selectedProduct
                                ? `₹${totalPrice}`
                                : ""
                        }
                        readOnly
                        placeholder="Total price"
                    />

                    {/* ADD */}

                    <button
                        onClick={handleAdd}
                        disabled={!customer}
                    >
                        Add
                    </button>

                </div>

                {/* =================================================
                    BALANCE
                ================================================= */}

                <input
                    onChange={(e) =>
                        setBalance(
                            Number(
                                e.target.value
                            )
                        )
                    }
                    style={{
                        width: "290px",
                        border: "2px solid black",
                        borderRadius: "5px",
                        paddingTop: "10px",
                        paddingBottom: "10px",
                        paddingLeft: "5px"
                    }}
                    type="number"
                    placeholder="Balance"
                />

                {/* =================================================
                    RESORT ITEMS
                ================================================= */}

                <h3
                    style={{
                        fontFamily:
                            "'Times New Roman', Times, serif"
                    }}
                >
                    Resort Items
                </h3>

                {cart.length === 0 ? (

                    <p
                        style={{
                            color: "grey",
                            fontFamily: "monospace",
                            fontSize: "15px"
                        }}
                    >
                        No items added
                    </p>

                ) : (

                    <table
                        className="itemDisplayTable"
                    >

                        <thead>

                            <tr>

                                <th>
                                    Customer
                                </th>

                                <th>
                                    Product
                                </th>

                                <th>
                                    Qty
                                </th>

                                <th>
                                    Price
                                </th>

                                <th>
                                    Total
                                </th>

                                <th>
                                    Action
                                </th>

                            </tr>

                        </thead>

                        <tbody>

                            {cart.map(
                                (item) => (

                                    <tr
                                        key={
                                            item.id
                                        }
                                    >

                                        <td>
                                            {
                                                selectedResortCustomer?.customer_name
                                            }
                                        </td>

                                        <td>

                                            {
                                                item.product
                                            }

                                            {item.packSize
                                                ? ` (${item.packSize}g)`
                                                : ""}

                                        </td>

                                        <td>
                                            {
                                                item.quantity
                                            }
                                        </td>

                                        <td>
                                            ₹
                                            {
                                                item.price
                                            }
                                        </td>

                                        <td>
                                            ₹
                                            {
                                                item.total
                                            }
                                        </td>

                                        <td>

                                            <button
                                                onClick={() =>
                                                    handleDelete(
                                                        item.id
                                                    )
                                                }
                                            >
                                                Delete
                                            </button>

                                        </td>

                                    </tr>

                                )
                            )}

                        </tbody>

                    </table>

                )}

                {/* =================================================
                    ONLY FOR CUSTOMERS
                ================================================= */}

                <h2>
                    Only for customers
                </h2>

                <div className="inputDetailsForCustomers">

                    <input
                        className="customerName"
                        type="text"
                        placeholder="Enter Name"
                        value={cust}
                        onChange={(e) =>
                            setCust(
                                e.target.value
                            )
                        }
                    />

                    <input
                        className="customerAddr"
                        type="text"
                        placeholder="Enter Address"
                        value={addr}
                        onChange={(e) =>
                            setAddr(
                                e.target.value
                            )
                        }
                    />

                    <select
                        value={custProduct}
                        onChange={(e) =>
                            setCustProduct(
                                e.target.value
                            )
                        }
                    >

                        <option value="">
                            Select product
                        </option>

                        {productForCustomers.map(
                            (p) => (

                                <option
                                    key={p}
                                    value={p}
                                >
                                    {p}
                                </option>

                            )
                        )}

                    </select>

                    <input
                        className="customerQuantity"
                        type="number"
                        placeholder="Enter Quantity"
                        value={custQuanity}
                        min="1"
                        onChange={(e) =>
                            setCustQuantity(
                                Number(
                                    e.target.value
                                )
                            )
                        }
                    />

                    <select
                        value={custunit}
                        onChange={(e) =>
                            setCustUnit(
                                e.target.value
                            )
                        }
                    >

                        <option value="">
                            Select Unit
                        </option>

                        {units.map(
                            (unit) => (

                                <option
                                    key={unit}
                                    value={unit}
                                >
                                    {unit}
                                </option>

                            )
                        )}

                    </select>

                    <br />

                    <span
                        style={{
                            color: "red"
                        }}
                    >
                        Enter per kg price if you
                        are choosing gms/kg.
                    </span>

                    <br />
                    <br />

                    <input
                        placeholder="Enter Price"
                        type="number"
                        value={
                            customerPrice || ""
                        }
                        onChange={(e) =>
                            setCustomerPrice(
                                Number(
                                    e.target.value
                                )
                            )
                        }
                    />

                    <input
                        type="text"
                        value={
                            custTotalPrice
                                ? `₹${custTotalPrice}`
                                : ""
                        }
                        readOnly
                        placeholder="Total price"
                    />

                    <br />

                    <button
                        onClick={
                            handleAddCustomer
                        }
                    >
                        Add
                    </button>

                </div>

                {/* =================================================
                    NORMAL CUSTOMER CART
                ================================================= */}

                <h3
                    style={{
                        fontFamily:
                            "'Times New Roman', Times, serif"
                    }}
                >
                    Customer Items
                </h3>

                {customerCart.length === 0 ? (

                    <p
                        style={{
                            color: "grey",
                            fontFamily: "monospace",
                            fontSize: "15px"
                        }}
                    >
                        No customer items added
                    </p>

                ) : (

                    <table
                        className="itemDisplayTable"
                    >

                        <thead>

                            <tr>

                                <th>
                                    Customer
                                </th>

                                <th>
                                    Product
                                </th>

                                <th>
                                    Qty
                                </th>

                                <th>
                                    Unit Price
                                </th>

                                <th>
                                    Total
                                </th>

                                <th>
                                    Action
                                </th>

                            </tr>

                        </thead>

                        <tbody>

                            {customerCart.map(
                                (item) => (

                                    <tr
                                        key={
                                            item.id
                                        }
                                    >

                                        <td>
                                            {
                                                item.cust
                                            }
                                        </td>

                                        <td>
                                            {
                                                item.custProduct
                                            }
                                        </td>

                                        <td>
                                            {
                                                item.custQuanity +
                                                item.custunit
                                            }
                                        </td>

                                        <td>
                                            ₹
                                            {
                                                item.customerPrice
                                            }
                                        </td>

                                        <td>
                                            ₹
                                            {
                                                item.custtotal
                                            }
                                        </td>

                                        <td>

                                            <button
                                                onClick={() =>
                                                    handleDeleteForCustomers(
                                                        item.id
                                                    )
                                                }
                                            >
                                                Delete
                                            </button>

                                        </td>

                                    </tr>

                                )
                            )}

                        </tbody>

                    </table>

                )}

                {/* =================================================
                    TOTAL
                ================================================= */}

                <h2>
                    Total: ₹{grandTotal}
                </h2>

                {/* =================================================
                    PRINT / NEW BILL
                ================================================= */}

                <button
                    onClick={handlePrint}
                    disabled={
                        savingOrder
                    }
                    style={{
                        position:
                            "relative",
                        zIndex: "10000"
                    }}
                >
                    {savingOrder
                        ? "Saving..."
                        : "Print"}
                </button>

                {cart.length > 0 && (

                    <button
                        onClick={
                            handleNewBill
                        }
                        disabled={
                            savingOrder
                        }
                        style={{
                            position:
                                "relative",
                            zIndex:
                                "10000",
                            marginLeft:
                                "10px"
                        }}
                    >
                        New Bill
                    </button>

                )}

                {/* =================================================
                    PRINT BILL
                ================================================= */}

                <div className="printBill">

                    <div className="billHeader">
                        Credit Bill
                    </div>

                    <div className="ownerDetails">

                        <div className="ownerDetailsLeft">

                            <span>
                                {msme}
                            </span>

                            <br />

                        </div>

                        <div className="ownerDetailsRight">

                            <img
                                src={logoblack}
                                style={{
                                    width: "50px"
                                }}
                                alt="logo"
                            />

                            <br />

                            <span
                                style={{
                                    fontSize:
                                        "15px"
                                }}
                            >
                                The Yercaud Bean
                            </span>

                            <br />

                            <span>
                                Lady's seat Rd,
                            </span>

                            <br />

                            <span>
                                Yercaud.
                            </span>

                            <br />

                            9994797824
                            <br />
                            8489333469

                        </div>

                    </div>

                    {/* CUSTOMER DETAILS */}

                    <div className="customerDetails">

                        <div className="toAddr">

                            <span
                                style={{
                                    fontWeight:
                                        "bold"
                                }}
                            >
                                BILL NO:
                            </span>

                            {" "}
                            {billNo}

                            <br />

                            <span
                                style={{
                                    fontWeight:
                                        "bold"
                                }}
                            >
                                BILLING TO:
                            </span>

                            <br />

                            {cust
                                ? cust
                                : selectedResortCustomer?.customer_name ||
                                  ""}

                            <br />

                            {addr
                                ? addr
                                : selectedResortCustomer?.address ||
                                  ""}

                            .

                        </div>

                        <div className="toDate">

                            <span
                                style={{
                                    fontWeight:
                                        "bold"
                                }}
                            >
                                BILLING DATE:
                            </span>

                            <br />

                            {formatDate(
                                selectedDate
                            )}

                        </div>

                    </div>

                    {/* BILL ITEMS */}

                    <table className="itemTable">

                        <tbody>

                            <tr
                                className="itemDisplayHeader"
                            >

                                <td
                                    style={{
                                        width:
                                            "50px"
                                    }}
                                >
                                    S No.
                                </td>

                                <td>
                                    Description
                                </td>

                                <td
                                    style={{
                                        width:
                                            "90px"
                                    }}
                                >
                                    Quantity
                                </td>

                                <td
                                    style={{
                                        width:
                                            "90px"
                                    }}
                                >
                                    Unit Price
                                </td>

                                <td
                                    style={{
                                        width:
                                            "90px"
                                    }}
                                >
                                    Total Price
                                </td>

                            </tr>

                            {/* RESORT ITEMS */}

                            {cart.map(
                                (
                                    item,
                                    index
                                ) => (

                                    <tr
                                        key={
                                            item.id
                                        }
                                        className="itemDisplay"
                                    >

                                        <td
                                            style={{
                                                textAlign:
                                                    "center"
                                            }}
                                        >
                                            {index +
                                                1}
                                        </td>

                                        <td
                                            style={{
                                                paddingLeft:
                                                    "5px"
                                            }}
                                        >

                                            {
                                                item.product
                                            }

                                            {item.packSize
                                                ? ` (${item.packSize}g)`
                                                : ""}

                                        </td>

                                        <td
                                            style={{
                                                textAlign:
                                                    "center"
                                            }}
                                        >
                                            {
                                                item.quantity
                                            }
                                        </td>

                                        <td
                                            style={{
                                                textAlign:
                                                    "center"
                                            }}
                                        >
                                            ₹
                                            {
                                                item.price
                                            }
                                        </td>

                                        <td
                                            style={{
                                                textAlign:
                                                    "center"
                                            }}
                                        >
                                            ₹
                                            {
                                                item.total
                                            }
                                        </td>

                                    </tr>

                                )
                            )}

                            {/* NORMAL CUSTOMER ITEMS */}

                            {customerCart.map(
                                (
                                    item,
                                    index
                                ) => (

                                    <tr
                                        key={
                                            item.id
                                        }
                                        className="itemDisplay"
                                    >

                                        <td
                                            style={{
                                                textAlign:
                                                    "center"
                                            }}
                                        >
                                            {
                                                cart.length +
                                                index +
                                                1
                                            }
                                        </td>

                                        <td
                                            style={{
                                                paddingLeft:
                                                    "5px"
                                            }}
                                        >
                                            {
                                                item.custProduct
                                            }
                                        </td>

                                        <td
                                            style={{
                                                textAlign:
                                                    "center"
                                            }}
                                        >
                                            {
                                                item.custQuanity +
                                                item.custunit
                                            }
                                        </td>

                                        <td
                                            style={{
                                                textAlign:
                                                    "center"
                                            }}
                                        >
                                            ₹
                                            {
                                                item.customerPrice
                                            }
                                        </td>

                                        <td
                                            style={{
                                                textAlign:
                                                    "center"
                                            }}
                                        >
                                            ₹
                                            {
                                                item.custtotal
                                            }
                                        </td>

                                    </tr>

                                )
                            )}

                            {/* BALANCE */}

                            {balance > 0 && (

                                <tr>

                                    <td
                                        style={{
                                            textAlign:
                                                "center"
                                        }}
                                    >
                                        {
                                            balanceSNo
                                        }
                                    </td>

                                    <td
                                        style={{
                                            paddingLeft:
                                                "5px"
                                        }}
                                    >
                                        Balance
                                    </td>

                                    <td
                                        style={{
                                            textAlign:
                                                "center"
                                        }}
                                        colSpan={2}
                                    >
                                        ₹{balance}
                                    </td>

                                    <td
                                        style={{
                                            textAlign:
                                                "center"
                                        }}
                                    >
                                        ₹{balance}
                                    </td>

                                </tr>

                            )}

                        </tbody>

                    </table>

                    {/* AMOUNT */}

                    <table className="amtTable">

                        <tbody>

                            <tr>

                                <td
                                    style={{
                                        paddingLeft:
                                            "5px"
                                    }}
                                >

                                    <span
                                        style={{
                                            fontWeight:
                                                "bold"
                                        }}
                                    >
                                        Amount in words:
                                    </span>

                                    {" "}

                                    {numberToWords(
                                        grandTotal
                                    )}

                                </td>

                                <td
                                    style={{
                                        width:
                                            "90px",
                                        textAlign:
                                            "center",
                                        borderRight:
                                            "1px white solid",
                                        fontWeight:
                                            "bold"
                                    }}
                                >
                                    Grand Total
                                </td>

                                <td
                                    style={{
                                        width:
                                            "90px",
                                        textAlign:
                                            "center"
                                    }}
                                >
                                    {grandTotal}
                                </td>

                            </tr>

                        </tbody>

                    </table>

                    {/* FOOTER */}

                    <div className="footer">

                        <div className="terms">

                            <span
                                style={{
                                    fontWeight:
                                        "bold"
                                }}
                            >
                                Terms & Condition
                                <sup>*</sup>
                            </span>

                            <br />

                            Payment must be paid
                            within 15 days
                            from the issue
                            of bill.

                        </div>

                        <div className="signature">

                            <img
                                src={esign1}
                                style={{
                                    width:
                                        "70px",
                                    marginLeft:
                                        "350px"
                                }}
                                alt="signature"
                            />

                            <br />

                            Signature

                        </div>

                    </div>

                </div>

            </div>

        </div>
    );
}

export default MainPage;
